/**
 * Planet Ops: signatures drawn on the app's own signature pad (apps/web/src/features/field/SignaturePad.tsx),
 * captured in Chromium at 2x by drawing on the component with a pointer, as a customer does:
 *   full      a signature of several strokes
 *   short     a short signature: two quick strokes, still a signature
 *   initials  initials on the smaller initials pad (90 px tall)
 *   dot       a single tap: not a signature
 *   blank     the pad exported with nothing drawn: not a signature
 * Used by the drawn-signature checks (lib/drawnSignature.ts) and the signing tests.
 */
export const PAD_FULL =
  "data:image/png;base64,";
export const PAD_SHORT =
  "data:image/png;base64,";
export const PAD_INITIALS =
  "data:image/png;base64,";
export const PAD_DOT =
  "data:image/png;base64,";
export const PAD_BLANK =
  "data:image/png;base64,";

/** A valid but one-pixel PNG: the old stand-in for a signature, which no longer passes. */
export const ONE_PIXEL = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=";
